"""Original category template extracted from select(), including live CSS transition behavior."""
from pathlib import Path
import re,json
r=Path(__file__).resolve().parents[2];out=r/'artifacts/replica/windows-download';js=(r/'docs/replica/source/original.js').read_text();raw=re.search(r'const categoryDefs=(\[.*?\]);',js).group(1);defs=json.loads(re.sub(r'(\w+):',r'"\1":',raw).replace("'",'"'));template=re.search(r'categoryDefs.map\(c=>(`<section class="category".*?</section>`)\)',js).group(1)
functions='\n'.join(l for l in js.splitlines() if l.startswith(('const esc=','const t=','const icons=','const icon=','const pill=','function press(')))
cases=[]
for lang in ['ko','en']:
 for width in [302,676,854,1060]:
  for d in defs+[dict(defs[-1],ready=True)]:
   i=0 if lang=='ko' else 1;key=d['key'];ready=d.get('ready',False);status=([('예시 준비됨','Sample ready'),('별도 DB 준비 필요','Test DB required')][not ready] if key=='trial' else ('일부 가능','Partial') if key=='access' else ('가능','Available'))[i];kind='warn' if key=='access' or key=='trial' and not ready else 'ok'
   for selected in [False,True]:
    for expanded in [False,True]:cases.append(dict(id=f'{lang}-{width}-{key}{"ready" if ready else ""}-{int(selected)}{int(expanded)}',key=key,lang=lang,width=width,title=d['name'][i],description=d['desc'][i],icon={'data':'db','schema':'grid','access':'shield','objects':'layers','trial':'play'}[key],statusText=status,statusKind=kind,selectionLabel=d['name'][i]+(' 검사 선택'if lang=='ko'else' check selection'),selected=selected,expanded=expanded,ready=ready,details=d['detail'if i==0 else'en']))
(out/'categorysection-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
script='''let lang='ko',state={selected:new Set(),expanded:new Set(),trial:{ready:false}},events=[];'''+functions+'\nconst defs='+json.dumps(defs,ensure_ascii=False)+';const cases='+json.dumps(cases,ensure_ascii=False)+';const card=c=>'+template+''';for(const c of cases){lang=c.lang;state.selected=new Set(c.selected?[c.key]:[]);state.expanded=new Set(c.expanded?[c.key]:[]);state.trial.ready=c.ready;const f=document.createElement('div');f.className='fixture';f.dataset.id=c.id;f.style.width=c.width+'px';f.innerHTML=card(defs.find(d=>d.key===c.key));if(c.id!==cases[0].id)f.setAttribute('aria-hidden','true');document.getElementById('fixtures').append(f)}function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const e=f.firstElementChild,r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},wrap=e.querySelector('.category-body-wrap'),s=getComputedStyle(e);return{id:f.dataset.id,width:r.width,height:r.height,header:box(e.querySelector('.category-head')),wrapper:box(wrap),body:box(e.querySelector('.category-body')),items:[...e.querySelectorAll('li')].map(n=>({box:box(n),text:n.textContent})),selected:e.querySelector('input').checked,expanded:e.querySelector('button').getAttribute('aria-expanded')==='true',hidden:wrap.getAttribute('aria-hidden')==='true',inert:wrap.inert,border:s.borderColor,shadow:s.boxShadow,visibility:getComputedStyle(wrap).visibility}})}document.getElementById('section-record').onclick=async()=>{await document.fonts.ready;const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read(),events})});if(!response.ok)throw Error('Evidence failed');document.getElementById('section-record').textContent='CategorySection recorded'};document.addEventListener('click',e=>{const b=e.target.closest('.category-toggle');if(!b)return;press(b);const expanded=b.getAttribute('aria-expanded')!=='true',wrap=b.closest('.category').querySelector('.category-body-wrap');b.setAttribute('aria-expanded',expanded);wrap.classList.toggle('is-open',expanded);wrap.setAttribute('aria-hidden',!expanded);wrap.inert=!expanded;events.push({action:'expand',value:expanded,trusted:e.isTrusted})});document.addEventListener('change',e=>{if(e.target.matches('[data-category]'))events.push({action:'select',value:e.target.checked,trusted:e.isTrusted})});'''
(out/'categorysection.html').write_text('''<!doctype html><meta charset="utf-8"><title>CategorySection · original isolation</title><link rel="stylesheet" href="categorysection-original.css"><style>body{min-width:1200px}.fixture{position:absolute;left:30px;top:30px}.fixture:not(:first-child){visibility:hidden;opacity:0;pointer-events:none}#section-record{position:fixed;right:20px;top:500px}</style><button id="section-record">Record CategorySection</button><div id="fixtures"></div><script>'''+script+'</script><script src="categorysection-motion.js"></script>')
for p in [out/'categorysection-cases.json',r/'docs/replica/source/categorysection-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'literal category sections prepared')

(out/'categorysection-motion.js').write_bytes((r/'tools/ReplicaProbe/category_section_motion.js').read_bytes())
